//
// Health-risk example — shared definitions (CKKS)
//
// Framingham 2008 office-based (BMI) 10-year cardiovascular risk, computed on
// encrypted inputs. design/twin.py is the plaintext model of exactly this code.
//
//   risk = g(u),  g(u) = 1 - exp(-exp(u)),  u = sum_i w_i * x_i
//
// Slot layout (16 of N/2 slots, every other slot zero):
//   0..7   male block   [ln age, ln bmi, ln sbp*(1-t), ln sbp*t, smoker, diabetic, 1, 0]
//   8..15  female block (same order)
// The patient fills only their own block, so the server never branches on sex
// or blood-pressure treatment: the weight vector covers both blocks and the
// empty one contributes zero.

#pragma once

#include "openfhe.h"

#include <cmath>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace health_risk {

using namespace lbcrypto;

constexpr uint32_t kBlock = 8;
constexpr uint32_t kSlotsUsed = 2 * kBlock;
const std::vector<int32_t> kRotations = {1, 2, 4, 8};  // rotate-and-sum over 16 slots

// CKKS parameters (design/DESIGN.md, Stage 6)
constexpr uint32_t kDepth = 8;           // 1 weights + 1 mask + 6 for the degree-27 curve
constexpr uint32_t kScalingModSize = 42; // bits of scale per level
constexpr uint32_t kFirstModSize = 57;   // 15 bits of headroom over the scale at decrypt
constexpr uint32_t kRingDim = 65536;     // 2^16: the ring the Fog runs

// Input contract the patient's side enforces before encrypting (inclusive).
// Age is the model's validity range; BMI and SBP are plausible clinical ranges.
struct Bounds { double lo, hi; };
constexpr Bounds kAge{30.0, 74.0};
constexpr Bounds kBmi{15.0, 50.0};
constexpr Bounds kSbp{90.0, 200.0};

struct Patient {
    bool male;
    double age, bmi, sbp;
    int bp_treated, smoker, diabetic;  // 0 or 1
};

// Empty string when the patient is inside the supported range, else the reason.
inline std::string out_of_range(const Patient& p) {
    auto chk = [](const char* name, double v, Bounds b) -> std::string {
        if (v >= b.lo && v <= b.hi) return "";
        std::ostringstream os;
        os << name << " " << v << " is outside the supported range " << b.lo << "-" << b.hi;
        return os.str();
    };
    for (auto s : {chk("age", p.age, kAge), chk("BMI", p.bmi, kBmi), chk("systolic BP", p.sbp, kSbp)})
        if (!s.empty()) return s;
    auto flag = [](int v) { return v == 0 || v == 1; };
    if (!flag(p.bp_treated) || !flag(p.smoker) || !flag(p.diabetic))
        return "yes/no inputs must be 0 or 1";
    return "";
}

// Client-side encoding: the logarithms and the slot placement happen in the
// clear, on the patient's own data.
inline std::vector<double> pack(const Patient& p) {
    std::vector<double> x(kSlotsUsed, 0.0);
    const double ls = std::log(p.sbp);
    const uint32_t off = p.male ? 0 : kBlock;
    x[off + 0] = std::log(p.age);
    x[off + 1] = std::log(p.bmi);
    x[off + 2] = ls * (1 - p.bp_treated);
    x[off + 3] = ls * p.bp_treated;
    x[off + 4] = p.smoker;
    x[off + 5] = p.diabetic;
    x[off + 6] = 1.0;  // carries the per-sex bias
    return x;
}

// The crypto context. Shared by the native keygen and the browser build, so
// both sides generate identical parameters.
inline CryptoContext<DCRTPoly> make_context(uint32_t ring_dim = kRingDim) {
    CCParams<CryptoContextCKKSRNS> parameters;
    // 128-bit security at the Fog's ring; a smaller test ring cannot meet it.
    parameters.SetSecurityLevel(ring_dim >= kRingDim ? HEStd_128_classic : HEStd_NotSet);
    parameters.SetRingDim(ring_dim);
    parameters.SetMultiplicativeDepth(kDepth);
    parameters.SetScalingModSize(kScalingModSize);
    parameters.SetFirstModSize(kFirstModSize);
    parameters.SetScalingTechnique(FLEXIBLEAUTO);

    CryptoContext<DCRTPoly> cc = GenCryptoContext(parameters);
    cc->Enable(PKE);
    cc->Enable(KEYSWITCH);
    cc->Enable(LEVELEDSHE);
    cc->Enable(ADVANCEDSHE);  // Chebyshev evaluation
    return cc;
}

// The risk curve the server approximates.
inline double risk_curve(double u) { return 1.0 - std::exp(-std::exp(u)); }

// Server-side model (data/model.txt, emitted by design/twin.py).
struct Model {
    std::vector<double> weights;  // kSlotsUsed slot weights, bias in slots 6 and 14
    double lo = 0, hi = 0;        // range the curve stand-in covers
    uint32_t degree = 0;
};

inline Model load_model(const std::string& path) {
    std::ifstream in(path);
    if (!in.is_open()) throw std::runtime_error("Failed to open model " + path);
    std::vector<std::string> lines;
    for (std::string line; std::getline(in, line);)
        if (!line.empty() && line[0] != '#') lines.push_back(line);
    if (lines.size() < 3) throw std::runtime_error("Malformed model " + path);
    Model m;
    std::istringstream w(lines[0]);
    for (double v; w >> v;) m.weights.push_back(v);
    std::istringstream(lines[1]) >> m.lo >> m.hi;
    std::istringstream(lines[2]) >> m.degree;
    if (m.weights.size() != kSlotsUsed || m.hi <= m.lo || m.degree == 0)
        throw std::runtime_error("Malformed model " + path);
    return m;
}

// The circuit. Called by the server in every mode, so --cpu, the simulator and
// the Fog run identical math.
inline Ciphertext<DCRTPoly> run_circuit(CryptoContext<DCRTPoly>& cc, const Model& m,
                                        const Ciphertext<DCRTPoly>& ct_x) {
    // 1. weighted inputs (the weights stay on the server as a plaintext)
    auto pt_w = cc->MakeCKKSPackedPlaintext(m.weights);
    auto ct = cc->EvalMult(ct_x, pt_w);

    // 2. rotate-and-sum: slot 0 ends up holding u, the sum over all 16 slots
    for (int32_t r : kRotations)
        ct = cc->EvalAdd(ct, cc->EvalRotate(ct, r));

    // 3. keep slot 0 only: the other slots hold partial sums that can fall
    //    outside the curve's range, where the stand-in polynomial blows up
    std::vector<double> e0(kSlotsUsed, 0.0);
    e0[0] = 1.0;
    ct = cc->EvalMult(ct, cc->MakeCKKSPackedPlaintext(e0));

    // 4. the risk curve
    ct = cc->EvalChebyshevFunction(risk_curve, ct, m.lo, m.hi, m.degree);

    // 5. one tower is all decrypt needs, and it is what travels back
    return cc->Compress(ct, 1);
}

}  // namespace health_risk
